#include <cstdio>
#include <algorithm>
using namespace std;

const int N = 1005;
const int E = 2005;

int n, m;
int h[N], to[E], nx[E], et;
int id[N], od[N];
bool vis[N];
int q[N], ql, qr;
int ans[N], cnt;

bool chk(int ban) {
    ql = qr = 0;
    for (int i = 1; i <= n; i++) {
        vis[i] = (i == ban);
        if (!vis[i] && !id[i]) {
            q[++qr] = i;
            vis[i] = 1;
        }
    }
    while (ql < qr) {
        int u = q[++ql];
        for (int i = h[u]; i; i = nx[i]) {
            int v = to[i];
            if (vis[v])
                continue;
            if (!od[v])
                return 0;
            q[++qr] = v;
            vis[v] = 1;
        }
    }
    return 1;
}

int main() {
    scanf("%d%d", &n, &m);
    for (int i = 1; i <= m; i++) {
        int u, v;
        scanf("%d%d", &u, &v);
        to[++et] = v;
        nx[et] = h[u];
        h[u] = et;
        od[u]++;
        id[v]++;
    }
    for (int i = 1; i <= n; i++)
        if (chk(i))
            ans[++cnt] = i;
    printf("%d\n", cnt);
    for (int i = 1; i <= cnt; i++)
        printf("%d%c", ans[i], " \n"[i == cnt]);
    return 0;
}

#include <cstdio>
#include <algorithm>
using namespace std;

const int N = 2005;
const int mod = 1e9;

int n;
char s[N];
int f[N][N];

int main() {
    scanf("%d", &n);
    scanf("%s", s + 1);
    f[0][0] = 1;
    for (int i = 1; i <= n; i++)
        for (int j = 0; j <= n; j++) {
            f[i][j] = f[i - 1][j];
            if (s[i] == '(' && j)
                f[i][j] = (f[i][j] + f[i - 1][j - 1]) % mod;
            if (s[i] == ')' && j < n)
                f[i][j] = (f[i][j] + f[i - 1][j + 1]) % mod;
        }
    printf("%d\n", f[n][0]);
    return 0;
}
